.menu__desktop {
  position: fixed;
  top: 0;
  left: 0;
  height: 100%;
  z-index: 90;
  display: flex;
  align-items: center;
  padding-left: 50px;
  pointer-events: none;
  transform: translateX(-100%);
  opacity: 0;
  transition: transform 0.6s cubic-bezier(0.16, 1, 0.3, 1), opacity 0.6s ease;
}

.menu__desktop.active {
  transform: translateX(0);
  opacity: 1;
  pointer-events: auto;
}

.menu__items {
  display: flex;
  flex-direction: column;
  position: relative;
  gap: 15px;
}

.menu__desktop-pretitle {
  color: rgba(245, 230, 211, 0.3);
  font-family: var(--font-unbounded);
  font-size: 0.65rem;
  letter-spacing: 4px;
  margin-bottom: 20px;
  padding-left: 20px;
}

